    # to the parity of the interior dimensions. Isolated 3x3 motif centers
    # are separately recolored as the small odd motif convention.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or seen[r][c]:
                continue
            q = deque([(r, c)])
