            # is an additional marker and is colored 7.
            if r1-r0 == 2 and c1-c0 == 2 and len(component) == 8:
                centers = [(rr,cc) for rr in range(r0+1,r1) for cc in range(c0+1,c1)
                           if grid[rr][cc] == background]
                if len(centers) == 1:
                    rr,cc=centers[0]
                    out[rr][cc]=7
    return out


